java.solution:
import java.util.Scanner;

public class Main {
    static int[] swapValues(int a, int b) {
        int temp = a;
        a = b;
        b = temp;
        return new int[] {a, b};
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int a = in.nextInt();
        int b = in.nextInt();
        int[] swapped = swapValues(a, b);
        System.out.println(swapped[0] + " " + swapped[1]);
    }
}

